mapper.select:
SELECT *
FROM activity_intervals
WHERE device_binding_id = #{deviceBindingId}
  AND start_at < #{toTime}
  AND (end_at IS NULL OR end_at > #{fromTime})
ORDER BY start_at ASC, id ASC

mapper.delete:
DELETE FROM activity_intervals
WHERE device_binding_id = #{deviceBindingId}
  AND start_at < #{toTime}
  AND (end_at IS NULL OR end_at > #{fromTime})

mapper.update:
UPDATE activity_intervals
SET end_at = #{maxInstant},
    quality = 'TRUNCATED',
    end_reason = 'MAX_DURATION',
    updated_at = #{now}
WHERE device_binding_id = #{deviceBindingId}
  AND end_at IS NULL
  AND start_at < #{maxInstant}

mapper.select:
SELECT ai.*
FROM activity_intervals ai
LEFT JOIN monitored_apps ma ON ai.monitored_app_id = ma.id
WHERE ai.device_binding_id = #{deviceBindingId}
  AND ai.start_at < #{toTime}
  AND (ai.end_at IS NULL OR ai.end_at > #{fromTime})

      AND ma.app_key = #{appKey}

ORDER BY ai.start_at ASC, ai.id ASC
LIMIT #{limit}
